(* [comment removed for export] *)
Definition pch_side (m : mem) (P E p0 n lo shi : Z) : Prop := pside2 m lo shi [(P, 296); (E, 24); (p0, n)] [(E, 24)].

Lemma pch_side_intro : forall m P E p0 n lo shi,
  ACONST m -> stack0 m lo shi -> AXStatics2 m -> accessible m P 296 -> accessible m E 24 -> accessible m p0 n ->
  shvis m E (E + 24) -> aapp E 24 -> pch_side m P E p0 n lo shi.
Proof.
  intros m P E p0 n lo shi AC SK XS AP AE AW SV APE. apply pside2_intro; [exact AC| exact SK| exact XS| |].
  - apply Forall_cons; [exact AP| apply Forall_cons; [exact AE| apply Forall_cons; [exact AW| apply Forall_nil]]].
  - apply Forall_cons; [| apply Forall_nil]. cbn [fst snd]. apply shv_entry; [exact APE| lia| exact SV].
Qed.

Lemma pch_pwin : forall sp P IN E lo shi c p0 bs, pch_pure sp P IN E lo shi c p0 bs -> Forall pwin (pch_W lo sp P IN E).
Proof.
  intros sp P IN E lo shi c p0 bs (_ & _ & _ & ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL) & _).
  unfold pch_W, PCH_STACK, AASSIGN_STACK, AINTRIN_STACK in *. repeat apply Forall_cons; [| | | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APP| clear; lia| clear; lia].
  - apply pwin_stack. clear - CEIL LO ILO. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Definition pch_saved (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list cell :=
  [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition pch_ctx (m m1 : mem) (sp : word) (SV : list cell) (P IN E lo shi : Z)
    (c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (pv : Z) (lowc ecs : list cell) (g : bool) (junk : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -160) lowc
  /\ rw_cells asegs m1 (bv_unsigned sp + -136) [C8 (wz pv)]
  /\ rw_cells asegs m1 (bv_unsigned sp + -128) [CB 24 junk]
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells asegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells asegs m1 IN [C8 (wz p0)]
  /\ rw_cells asegs m1 E ecs
  /\ rw_cells asegs m1 (P + 288) [C8 (wz 0)]
  /\ bytes_at asegs m1 p0 bs
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo (bv_unsigned sp + -160)
  /\ munch (pch_W lo sp P IN E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ pch_side m P E p0 (Z.of_nat (length bs)) lo shi.

(* [comment removed for export] *)
Definition pch_fcore (c c1 : pcore) (n : Z) : Prop :=
  pc_state c1 = pc_state c /\ pc_f c1 = pc_f c /\ pc_hlim c1 = pc_hlim c /\ pc_len c1 = pc_len c
  /\ pc_len0 c1 = pc_len0 c /\ pc_blim_has c1 = pc_blim_has c /\ 0 <= pc_blim c1 <= pc_blim c
  /\ 0 <= pc_skip c1 /\ (pc_skip c1 <= pc_skip c \/ pc_skip c1 < n)
  /\ 0 <= pc_skip c1 < 2^64 /\ 0 <= pc_f c1 < 2^14 /\ 0 <= pc_hlim c1 < 2^31.

Lemma pch_fail_exit : forall c c1 n e loc,
  pch_fcore c c1 n -> In e [HE_NEED_MORE; HE_BAD_CHUNK; HE_BAD_LINE_ENDING; HE_BAD_CHUNK_EXTENSION; HE_BODY_LIMIT] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 ->
  pch_fail c c1 n (EC_http_loc e loc).
