(* [comment removed for export] *)
Definition pch_exitA_stmt (k : nat) (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0x t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pv : Z) (e1 e2 e3 : word) (g : bool) (j24 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs pv
          [CB 24 j24] [C8 e1; C8 e2; C8 e3] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  In e [HE_NEED_MORE; HE_BAD_CHUNK; HE_BAD_LINE_ENDING; HE_BAD_CHUNK_EXTENSION; HE_BODY_LIMIT] ->
  evt asegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp (pick k 1 (shw (E + 16)) t0x) t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x (pick k 2 (shw (E + 16)) s3x) s4x
              (match k with O => s5x | _ => wz (E + 16) end)
              (pick k 3 (shw (E + 16)) s6x) s7x s8x (wz 2147450880) s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

Local Ltac pch_exitA_script k e loc CHK :=
  unfold pch_exitA_stmt;
  intros rax ra sp gp tp t0x t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
         F fc m m1 P IN E lo shi c c1 pad7 pad2 p0 bs pv e1 e2 e3 g j24 junk;
  intros CTX PURE FC HE;
  destruct CTX as (FR0 & PCL & TMP & FRhi & PC & IT & EC & CBH & WIN & HC & ST & MU & WM & MI & SIDE);
  pose proof (pch_pwin _ _ _ _ _ _ _ _ _ PURE) as FW;
  destruct PURE as (PCOK & SK62 & N62 & ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL) & APP2 & DPE2 & APW & DWP & DWE);
  pose proof (ex_bnd_intro _ _ _ _ _ LO CEIL SHI APE) as BND;
  pose proof BND as BNDv; unfold ex_bnd in BNDv; destruct BNDv as (_ & _ & _ & SPR & EB1 & EB2 & EB3 & EB4 & AF1);
  pose proof (stack0_bounds _ _ _ (pside2_stack0 _ _ _ _ _ SIDE)) as [SKB1 SKB2];
  pose proof (aapp_bounds _ 296 APP2 ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APW ltac:(lia)) as (WB1 & WB2 & WB3 & WB4 & WB5);
  assert (D8 : (bv_unsigned sp + -128) mod 8 = 0) by (clear - SPAL; Z.div_mod_to_equations; lia);
  clear SPAL PB5 WB5 PAL APP APP2 APW DPE PCOK; hydeL DPE2; hydeL DWP; hydeL DWE; hydeL EAL; hydeL IAL; hydeL D8;
  unfold pch_W, pch_saved, PCH_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold pick, shw; cbn [Nat.eqb];
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold wz in *;
  destruct (rw_cells_forget _ _ _ _ EC) as [ej EC2]; cbn [cells_size csize Nat.add] in EC2; clear EC;
  assign_loc_core MEMCPY ASSIGNA SIDE MU WM FW HC TMP EC2 ST MI APE D8 BND (bv_unsigned sp + -128) E e loc lo shi sp g junk ej m;
  assign_loc_chk SIDE FW EAL E m CHK;
  (* [comment removed for export] *)
  st1;
  steps_to 0xcf03c%Z;
  lazymatch goal with
  | TMPa : rw_cells _ _ (bv_unsigned sp + -128) [C8 _; C8 _], TMPb : rw_cells _ _ (bv_unsigned sp + -112) [C8 _],
    ST3 : stk _ _ lo (bv_unsigned sp + -160) |- _ =>
      join_frameA TMPa TMPb (bv_unsigned sp + -128); join_frameA TMPa FRhi (bv_unsigned sp + -128);
      join_frameA PCL TMPa (bv_unsigned sp + -136); join_frameA FR0 PCL (bv_unsigned sp + -160);
      step; release_frame FR0 ST3 (bv_unsigned sp)
  end;
  step;
  assign_loc_close SIDE FW BND E e loc m;
  pch_finish p0 (EC_http_loc e loc) c1 true;
  right; split; [reflexivity|]; apply (pch_fail_exit _ _ _ _ _ FC HE); [reflexivity | clear; lia | clear; lia].

